package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class LegacyReportLinksTest {
 @Test void missingConfigurationNeverProducesAPlaceholderOrProductionDefault(){assertEquals(409,assertThrows(BusinessException.class,()->new LegacyReportLinks("","").detail(7)).getCode());assertEquals(409,assertThrows(BusinessException.class,()->new LegacyReportLinks("https://petlis.invalid/","").detail(7)).getCode());}
 @Test void configuredUrlUsesExactOriginalPathAndCipher(){var links=new LegacyReportLinks("https://petlis.invalid/","petlis-public-test-key");assertEquals("https://petlis.invalid/Project/View/Detail.aspx?CID="+LegacyLinkCodec.encrypt("7","petlis-public-test-key"),links.detail(7));assertTrue(links.detail(0).contains("?CID="));assertThrows(BusinessException.class,()->links.detail(-1));}
 @Test void hospitalUsesOriginalHospIdParameterWithoutChangingDetailLinks(){var links=new LegacyReportLinks("https://petlis.invalid/","petlis-public-test-key");assertEquals("https://petlis.invalid/Project/View/Detail.aspx?HospID="+LegacyLinkCodec.encrypt("7","petlis-public-test-key"),links.hospital(7));assertTrue(links.detail(7).contains("?CID="));}
 @Test void invalidBaseAndEmbeddedCredentialsAreRejected(){for(String base:new String[]{"javascript:alert(1)","https://user:pass@petlis.invalid/","https://petlis.invalid/?x=1","/relative/"})assertThrows(BusinessException.class,()->new LegacyReportLinks(base,"test-key").detail(7));}
 @Test void decodeRequiresPrivatePhraseAndOnlyReturnsValidOriginalNumericIds(){var links=new LegacyReportLinks("","public-customer-view-test");assertEquals(4294967295L,links.decodeId(LegacyLinkCodec.encrypt("4294967295","public-customer-view-test")));assertEquals(409,assertThrows(BusinessException.class,()->new LegacyReportLinks("","").decodeId("anything")).getCode());assertEquals(400,assertThrows(BusinessException.class,()->links.decodeId(LegacyLinkCodec.encrypt("0","public-customer-view-test"))).getCode());assertEquals(400,assertThrows(BusinessException.class,()->links.decodeId(LegacyLinkCodec.encrypt("notAnId","public-customer-view-test"))).getCode());}
}
